insert into public.projects(id,data,sort_order,published) values ('water','{"id":"water","number":"01","category":"Smart metering","title":"Smart ultrasonic water meter","subtitle":"Precision sensing. Connected infrastructure.","role":"Product Developer · PCB Designer · Firmware Developer","description":"A custom ultrasonic water meter for cold and hot water applications. Developed for water-management deployments in Ethiopia, the product brings sensing electronics, embedded control and remote monitoring into one system.","contribution":"PCB design in Altium Designer and firmware development using C, C++ and legacy assembly. My work connects the measurement hardware with the embedded application.","tags":["Altium Designer","C / C++","Ultrasonic sensing"],"facts":[["Application","Cold & hot water"],["Hardware","Custom PCB"],["Firmware","C · C++ · Assembly"]],"highlights":["Ultrasonic flow measurement for water management","Custom electronics and embedded application development","Deployment experience in Ethiopia"],"cover":"project1.jpg","images":[["project1.jpg","Water meter product"],["ultrasonic-2.jpg","Assembled meter units"],["ultrasonic-3.jpg","Electronics inside the enclosure"],["ultrasonic-4.jpg","Battery and enclosure assembly"],["ultrasonic-5.jpg","Meter PCB and communications hardware"]]}'::jsonb,0,true) on conflict(id) do nothing;
insert into public.projects(id,data,sort_order,published) values ('energy','{"id":"energy","number":"02","category":"Smart metering","title":"Energy meter add-on module","subtitle":"A smarter meter. Without a full replacement.","role":"Hardware Design Engineer · Product Developer","description":"An external module that adds remote monitoring and relay control to compatible digital and semi-analog energy meters. The design communicates through the existing infrared interface to reduce the need for complete meter replacement.","contribution":"Hardware design and product development for the optical reader and communications module.","tags":["IEC 62056","LTE / 4G","Optical communication"],"facts":[["Interface","Optical TX / RX"],["Modem","A7680C"],["Control","Remote relay"]],"highlights":["IEC 62056-compatible optical communication","A7680C LTE / 4G connectivity","Remote relay control for connection and disconnection","Designed for scalable smart metering deployments"],"cover":"energy-1.jpg","images":[["energy-1.jpg","Manufactured circuit boards"],["energy-2.jpg","Optical reader PCB design"],["energy-3.jpg","Meter enclosure reference"]]}'::jsonb,1,true) on conflict(id) do nothing;
insert into public.projects(id,data,sort_order,published) values ('sole','{"id":"sole","number":"03","category":"Connected devices","title":"Smart GPS sole & wireless charger","subtitle":"Connected safety, integrated into footwear.","role":"Hardware Design Engineer · Firmware Developer","description":"SmartTrack Shoes by Iconic Smart Solution integrate tracking and a discreet SOS feature into footwear. The system is intended to support children and adults at risk of wandering, with a removable electronics module and wireless charging.","contribution":"Hardware design and firmware development for the smart sole and its custom 5 W Qi 1.2 wireless charging system.","tags":["GPS / GNSS","Qi 1.2","Li-ion charging"],"facts":[["Charging","5 W wireless"],["Battery","3.7 V Li-ion"],["Functions","Tracking · SOS"]],"highlights":["Location tracking, geofencing and SOS functions through a companion app","Transmitter design with integrated AC-to-DC conversion","Receiver with Qi rectifier and CC/CV battery charging controller","Motion sensing and a removable tracking module"],"cover":"smartsole-3.jpg","images":[["smartsole-3.jpg","Circular charging PCB render"],["smartsole-1.jpg","Component-side board design"],["smartsole-2.jpg","Charging electronics layout"],["smartsole-4.jpg","Iconic board reverse side"],["smartsole-5.jpg","Smart sole electronics render"]]}'::jsonb,2,true) on conflict(id) do nothing;
insert into public.projects(id,data,sort_order,published) values ('switch','{"id":"switch","number":"04","category":"Industrial systems","title":"5-port Gigabit Ethernet switch","subtitle":"Compact footprint. High-speed connections.","role":"Networking hardware project","description":"A compact Ethernet switch for industrial systems, small offices and other wired networking applications. Five Gigabit ports, a wide input voltage range and a six-layer board form the core of the design.","contribution":"Compact multilayer networking hardware combining five Gigabit ports, a six-layer board and wide-range power input.","tags":["Realtek RTL8367","6-layer PCB","Gigabit Ethernet"],"facts":[["Ports","5 × Gigabit"],["Data rate","10/100/1000 Mbps"],["Input","5–60 V"]],"highlights":["Realtek RTL8367 Ethernet switch architecture","Five 10/100/1000 Mbps Ethernet ports","5–60 V input range","Compact six-layer printed circuit board"],"cover":"switch-1.jpg","images":[["switch-1.jpg","Powered hardware prototype"],["switch-2.jpg","Six-layer switch board render"],["switch-3.jpg","Component-side PCB render"],["switch-4.jpg","Reverse-side board layout"]]}'::jsonb,3,true) on conflict(id) do nothing;
insert into public.projects(id,data,sort_order,published) values ('node','{"id":"node","number":"05","category":"Industrial systems","title":"Multi-protocol communication node","subtitle":"One board. Industrial-grade versatility.","role":"Industrial embedded hardware project","description":"A four-layer STM32H743-based board combining Ethernet, dual CAN FD and nine-axis motion sensing. Designed for industrial automation, motion sensing, data logging and high-performance embedded applications.","contribution":"Project focus: integration of embedded processing, industrial communication and motion sensing on a single board.","tags":["STM32H743","CAN FD","BNO085"],"facts":[["Processor","Arm Cortex-M7"],["PCB","4 layers"],["Input","4–60 V"]],"highlights":["10/100 Mbps Ethernet interface using W5500","Two CAN FD ports with TCAN-FD interfaces","BNO085 accelerometer, gyroscope and magnetometer","External flash memory and USB 2.0 Type-C"],"cover":"node-1.jpg","images":[["node-1.jpg","Assembled communication board"],["node-3.jpg","Communication node PCB render"],["node-2.jpg","Reverse-side PCB layout"],["node-4.jpg","Component-side board layout"]]}'::jsonb,4,true) on conflict(id) do nothing;
